+import io.vertx.sqlclient.Pool;
+import io.vertx.sqlclient.PoolOptions;
+import io.vertx.sqlclient.PrepareOptions;
+import io.vertx.sqlclient.PreparedQuery;
+import io.vertx.sqlclient.Query;
+import io.vertx.sqlclient.Row;
+import io.vertx.sqlclient.RowSet;
+import io.vertx.sqlclient.SqlClient;
+import io.vertx.sqlclient.SqlConnection;
+
+/**
+ * Compatibility adapter for Vert.x 4 callers. Vert.x 5 creates PostgreSQL pools through
+ * {@link PgBuilder}; this class keeps older production and test code source-compatible.
+ */
+public final class PgPool implements Pool {
+
+  private final Pool delegate;
+
+  private PgPool(Pool delegate) {
+    this.delegate = delegate;
+  }
+
+  public static PgPool pool(Vertx vertx, PgConnectOptions connectOptions, PoolOptions poolOptions) {
+    return new PgPool(PgBuilder.pool()
+        .using(vertx)
+        .connectingTo(connectOptions)
+        .with(poolOptions)
+        .build());
+  }
+
+  public static SqlClient client(
+      Vertx vertx, PgConnectOptions connectOptions, PoolOptions poolOptions) {
+    return pool(vertx, connectOptions, poolOptions);
+  }
+
+  @Override
+  public Future<SqlConnection> getConnection() {
+    return delegate.getConnection();
+  }
+
+  @Override
+  public Query<RowSet<Row>> query(String sql) {
+    return delegate.query(sql);
+  }
+
+  @Override
+  public PreparedQuery<RowSet<Row>> preparedQuery(String sql) {
+    return delegate.preparedQuery(sql);
+  }
+
+  @Override
+  public PreparedQuery<RowSet<Row>> preparedQuery(String sql, PrepareOptions options) {
+    return delegate.preparedQuery(sql, options);
+  }
+
+  @Override
+  public Future<Void> close() {
+    return delegate.close();
+  }
+
+  @Override
+  public int size() {
+    return delegate.size();
+  }
+}
